/**
 * Mappers: BFF Statistics DTOs → frontend domain models.
 */

import type {
  StatisticsData,
  PerformanceStats,
  PerformanceScore,
  TrendDataPoint,
  PriorityDistribution,
  CategoryDistributionItem,
  MonthlyDataPoint,
  ActivityHeatmapData,
  AIInsight,
  TeamComparison,
  PersonalGoal,
  GoalsData,
  AchievementBadge,
  AchievementsData,
} from '../../models/Statistics';
import type {
  BffStatisticsDto,
  BffPersonalGoalDto,
  BffGoalsDataDto,
  BffAchievementBadgeDto,
  BffAchievementsDataDto,
  BffAIInsightDto,
  BffTeamComparisonDto,
  BffPerformanceStatsDto,
  BffPerformanceScoreDto,
  BffCategoryDistributionItemDto,
  BffTrendDataPointDto,
  BffMonthlyDataPointDto,
  BffActivityHeatmapDataDto,
  BffPriorityDistributionDto,
} from './responseModel';
import type { UUID } from '../../models/common';
import { StatisticsPeriod } from '../../models/Statistics';

export const mapBffPerformance = (dto: BffPerformanceStatsDto): PerformanceStats => ({
  totalTasks:         dto.totalTasks,
  completedTasks:     dto.completedTasks,
  completionRate:     dto.completionRate,
  totalTime:          dto.totalTime,
  averageTimePerTask: dto.averageTimePerTask,
  averageRating:      dto.averageRating,
  slaViolations:      dto.slaViolations,
  slaViolationRate:   dto.slaViolationRate,
  rank:               dto.rank,
  totalEmployees:     dto.totalEmployees,
  trend: {
    tasksChange:  dto.trend.tasksChange,
    ratingChange: dto.trend.ratingChange,
  },
});

export const mapBffScore = (dto: BffPerformanceScoreDto): PerformanceScore => ({
  overall:    dto.overall,
  rating:     dto.rating,
  percentile: dto.percentile,
  breakdown: {
    quality:       dto.breakdown.quality,
    speed:         dto.breakdown.speed,
    slaCompliance: dto.breakdown.slaCompliance,
  },
});

export const mapBffTrend = (dto: BffTrendDataPointDto): TrendDataPoint => ({
  label:         dto.label,
  completed:     dto.completed,
  slaViolations: dto.slaViolations,
});

export const mapBffPriority = (dto: BffPriorityDistributionDto): PriorityDistribution => ({
  urgent: dto.urgent,
  high:   dto.high,
  medium: dto.medium,
  low:    dto.low,
});

export const mapBffCategory = (dto: BffCategoryDistributionItemDto): CategoryDistributionItem => ({
  name:       dto.name,
  count:      dto.count,
  percentage: dto.percentage,
  color:      dto.color,
});

export const mapBffMonthly = (dto: BffMonthlyDataPointDto): MonthlyDataPoint => ({
  month:         dto.month,
  completed:     dto.completed,
  slaViolations: dto.slaViolations,
});

export const mapBffHeatmap = (dto: BffActivityHeatmapDataDto): ActivityHeatmapData => ({
  hour:  dto.hour,
  day:   dto.day,
  value: dto.value,
});

export const mapBffInsight = (dto: BffAIInsightDto): AIInsight => ({
  id:         dto.id as UUID,
  type:       dto.type as AIInsight['type'],
  title:      dto.title,
  message:    dto.message,
  icon:       dto.icon,
  color:      dto.color as AIInsight['color'],
  actionable: dto.actionable,
  action:     dto.action,
});

export const mapBffTeamComparison = (dto: BffTeamComparisonDto): TeamComparison => ({
  myAverage:      dto.myAverage,
  teamAverage:    dto.teamAverage,
  metric:         dto.metric,
  difference:     dto.difference,
  betterThanTeam: dto.betterThanTeam,
});

export const mapBffStatistics = (dto: BffStatisticsDto): StatisticsData => ({
  period:               dto.period as StatisticsPeriod,
  startDate:            dto.startDate,
  endDate:              dto.endDate,
  performance:          mapBffPerformance(dto.performance),
  score:                mapBffScore(dto.score),
  trends:               dto.trends.map(mapBffTrend),
  priorityDistribution: mapBffPriority(dto.priorityDistribution),
  categoryDistribution: dto.categoryDistribution.map(mapBffCategory),
  monthlyComparison:    dto.monthlyComparison.map(mapBffMonthly),
  activityHeatmap:      dto.activityHeatmap.map(mapBffHeatmap),
  insights:             dto.insights.map(mapBffInsight),
  teamComparison: {
    completionRate: mapBffTeamComparison(dto.teamComparison.completionRate),
    averageTime:    mapBffTeamComparison(dto.teamComparison.averageTime),
    qualityScore:   mapBffTeamComparison(dto.teamComparison.qualityScore),
  },
});

export const mapBffGoal = (dto: BffPersonalGoalDto): PersonalGoal => ({
  id:          dto.id as UUID,
  title:       dto.title,
  description: dto.description,
  target:      dto.target,
  current:     dto.current,
  unit:        dto.unit,
  progress:    dto.progress,
  deadline:    dto.deadline,
  status:      dto.status as PersonalGoal['status'],
  category:    dto.category as PersonalGoal['category'],
});

export const mapBffGoalsData = (dto: BffGoalsDataDto): GoalsData => ({
  goals:           dto.goals.map(mapBffGoal),
  achievementRate: dto.achievementRate,
});

export const mapBffBadge = (dto: BffAchievementBadgeDto): AchievementBadge => ({
  id:          dto.id as UUID,
  name:        dto.name,
  description: dto.description,
  icon:        dto.icon,
  unlockedAt:  dto.unlockedAt,
  rarity:      dto.rarity as AchievementBadge['rarity'],
  category:    dto.category as AchievementBadge['category'],
});

export const mapBffAchievements = (dto: BffAchievementsDataDto): AchievementsData => ({
  badges:         dto.badges.map(mapBffBadge),
  totalUnlocked:  dto.totalUnlocked,
  totalAvailable: dto.totalAvailable,
  recentUnlocks:  dto.recentUnlocks.map(mapBffBadge),
});
