import React, { useEffect, useState, useMemo } from 'react';
import { useAppDispatch, useAppSelector } from '../../store/hooks';
import { useAppToast } from '../../hooks/useAppToast';
import {
  fetchSLAAlerts,
  fetchSLAStats,
  escalateAlert,
  reassignAlert,
  fetchCandidateSuggestions,
  setFilters,
  updateCountdowns,
} from '../../store/slices/slaAlertsSlice';
import { SLAAlert, SLASeverity } from '../../models/SLAAlert';
import { AlertCard } from '../../components/sla-alerts/AlertCard';
import { AlertsStatsCards } from '../../components/sla-alerts/AlertsStatsCards';
import { AlertsFilters } from '../../components/sla-alerts/AlertsFilters';
import {
  EscalateModal,
  ReassignModal,
} from '../../components/sla-alerts/AlertActionModals';
import { TableCard, Pagination } from '../../components/common';
import { useMinLoadingTime } from '../../hooks/useMinLoadingTime';
import styles from './SLAAlertsPage.module.css';

const PAGE_SIZE = 15;

export const SLAAlertsPage: React.FC = () => {
  const dispatch = useAppDispatch();
  const toast = useAppToast();
  const {
    items,
    stats,
    candidates,
    filters,
    loading,
    statsLoading,
    candidatesLoading,
    actionLoading,
    error,
  } = useAppSelector((state) => state.slaAlerts);

  const [
    selectedAlert, setSelectedAlert
  ] = useState<SLAAlert | null>(null);
  const showLoading = useMinLoadingTime(loading);
  const [isEscalateModalOpen, setIsEscalateModalOpen] = useState(false);
  const [isReassignModalOpen, setIsReassignModalOpen] = useState(false);
  const [activeStatFilter, setActiveStatFilter] = useState<string>('all');
  const [currentPage, setCurrentPage] = useState(1);

  useEffect(() => {
    const timer = setTimeout(() => {
      dispatch(fetchSLAStats());
      dispatch(fetchSLAAlerts({ filters }));
    }, 0);
    return () => clearTimeout(timer);
  }, [dispatch, filters]);

  // Update countdowns every second
  useEffect(() => {
    const interval = setInterval(() => dispatch(updateCountdowns()), 1000);
    return () => clearInterval(interval);
  }, [dispatch]);

  // Reset to page 1 when filters or stat-card filter changes
  useEffect(() => { setCurrentPage(1); }, [filters, activeStatFilter]);

  const handleFiltersChange = (newFilters: typeof filters) => {
    dispatch(setFilters(newFilters));
  };

  const handleStatCardFilter = (severity: string) => {
    setActiveStatFilter(severity);
    dispatch(
      setFilters({
        ...filters,
        severity: severity === 'all' ? 'all' : (severity as SLASeverity),
      })
    );
  };

  const handleEscalate = (alert: SLAAlert) => {
    setSelectedAlert(alert);
    setIsEscalateModalOpen(true);
  };

  const handleReassign = async (alert: SLAAlert) => {
    setSelectedAlert(alert);
    await dispatch(fetchCandidateSuggestions({ alertId: alert.id }));
    setIsReassignModalOpen(true);
  };

  const refreshData = () => {
    dispatch(fetchSLAStats());
    dispatch(fetchSLAAlerts({ filters }));
  };

  const handleEscalateConfirm = async (
    alertId: string,
    reason: string,
    escalateTo?: string
  ) => {
    try {
      await dispatch(escalateAlert({ alertId, reason, escalateTo })).unwrap();
      setIsEscalateModalOpen(false);
      setSelectedAlert(null);
      refreshData();
    } catch (err: unknown) {
      toast.fromError(err, 'Không thể thực hiện leo thang, vui lòng thử lại');
    }
  };

  const handleReassignConfirm = async (
    alertId: string,
    relatedId: string,
    type: 'ticket' | 'task',
    newAssigneeId: string,
    newAssigneeName: string,
    reason: string
  ) => {
    try {
      await dispatch(
        reassignAlert({ alertId, relatedId, type, newAssigneeId, newAssigneeName, reason })
      ).unwrap();
      setIsReassignModalOpen(false);
      setSelectedAlert(null);
      refreshData();
    } catch (err: unknown) {
      toast.fromError(err, 'Không thể phân công lại, vui lòng thử lại');
    }
  };

  // ─── Client-side pagination ───────────────────────────────────────────────
  const totalPages = Math.ceil(items.length / PAGE_SIZE);
  const pagedItems = useMemo(
    () => items.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE),
    [items, currentPage]
  );

  return (
    <div className={styles.page}>

      {/* 1. Page Header */}
      <div className={styles.header}>
        <h1 className={styles.title}>
          <i className="fas fa-exclamation-triangle" />
          Cảnh báo SLA
        </h1>
      </div>

      {/* 2. Stats Cards (clickable to filter) */}
      <AlertsStatsCards
        stats={stats}
        loading={statsLoading}
        activeFilter={activeStatFilter}
        onFilter={handleStatCardFilter}
      />

      {/* 3. TableCard: Filters + List + Pagination */}
      <TableCard
        header={
          <AlertsFilters filters={filters} onFiltersChange={handleFiltersChange} />
        }
        footer={
          !loading && items.length > 0 ? (
            <Pagination
              currentPage={currentPage}
              totalPages={totalPages}
              totalCount={items.length}
              pageSize={PAGE_SIZE}
              onPageChange={setCurrentPage}
            />
          ) : undefined
        }
      >
        {error && (
          <div className={styles.errorBanner}>
            <i className="fas fa-times-circle" /> {error}
          </div>
        )}

        {showLoading && (
          <div className={styles.skeletonList}>
            {Array.from({ length: 6 }).map((_, i) => (
              <div key={i} className={styles.skeletonCard}>
                <div style={{ display: 'flex', gap: 12, alignItems: 'center' }}>
                  <div className={styles.skeletonPulse} style={{ width: 12, height: 40, borderRadius: 4, flexShrink: 0 }} />
                  <div style={{ flex: 1 }}>
                    <div className={styles.skeletonPulse} style={{ width: '55%', height: 15, marginBottom: 6 }} />
                    <div className={styles.skeletonPulse} style={{ width: '75%', height: 12 }} />
                  </div>
                  <div className={styles.skeletonPulse} style={{ width: 60, height: 22, borderRadius: 9999 }} />
                  <div className={styles.skeletonPulse} style={{ width: 80, height: 32, borderRadius: 6 }} />
                </div>
              </div>
            ))}
          </div>
        )}

        {!showLoading && pagedItems.length === 0 && (
          <div className={styles.empty}>
            <i className="fas fa-check-circle" />
            <h3>Không có cảnh báo SLA</h3>
            <p>Tất cả công việc đang trong SLA.</p>
          </div>
        )}

        {!showLoading && pagedItems.length > 0 && (
          <div className={styles.cardList}>
            {pagedItems.map((alert) => (
              <AlertCard
                key={alert.id}
                alert={alert}
                onEscalate={handleEscalate}
                onReassign={handleReassign}
              />
            ))}
          </div>
        )}
      </TableCard>

      <EscalateModal
        alert={selectedAlert}
        isOpen={isEscalateModalOpen}
        onClose={() => { setIsEscalateModalOpen(false); setSelectedAlert(null); }}
        onConfirm={handleEscalateConfirm}
        loading={actionLoading}
      />

      <ReassignModal
        alert={selectedAlert}
        isOpen={isReassignModalOpen}
        onClose={() => { setIsReassignModalOpen(false); setSelectedAlert(null); }}
        onConfirm={handleReassignConfirm}
        candidates={candidates}
        loading={actionLoading}
        candidatesLoading={candidatesLoading}
      />
    </div>
  );
};

