/**
 * Real BFF API calls for the unified messages endpoint.
 *
 * Route: /{entities}/{entityId}/messages
 * Where {entities} is "tickets" or "tasks".
 *
 * The entityType parameter ('ticket' | 'task') is mapped to the
 * route prefix automatically.
 */

import { UUID } from '../../models/common';
import { apiClient } from '../api';
import { BffResponse, unwrap } from '../shared/bffEnvelope';
import { BffMessageDto, BffMessagesPaginatedResponse } from './responseModel';
import { CreateMessageRequest, UpdateMessageRequest } from './requestModel';

/** Map entity type to route prefix. */
const routePrefix = (entityType: string): string => {
  if (entityType === 'ticket')   return 'tickets';
  if (entityType === 'incident') return 'medical-incidents';
  return 'tasks';
};

export const messageEndpoint = {
  /**
   * GET /{entities}/{entityId}/messages?type=message|comment&page=1&pageSize=20
   * Returns paginated messages with total count.
   * If type is omitted, returns ALL messages for the entity.
   */
  getMessages: async (
    entityType: string,
    entityId: UUID,
    type?: 'message' | 'comment',
    page: number = 1,
    pageSize: number = 20,
  ): Promise<BffMessagesPaginatedResponse> => {
    const prefix = routePrefix(entityType);
    const params = new URLSearchParams();
    if (type) params.append('type', type);
    params.append('page', page.toString());
    params.append('pageSize', pageSize.toString());

    const res = await apiClient.get<BffResponse<BffMessagesPaginatedResponse>>(
      `/${prefix}/${entityId}/messages?${params.toString()}`,
    );
    return unwrap(res);
  },

  /** POST /{entities}/{entityId}/messages */
  createMessage: async (
    entityType: string,
    entityId: UUID,
    dto: CreateMessageRequest,
  ): Promise<BffMessageDto> => {
    const prefix = routePrefix(entityType);
    const res = await apiClient.post<BffResponse<BffMessageDto>>(
      `/${prefix}/${entityId}/messages`,
      dto,
    );
    return unwrap(res);
  },

  /** PUT /{entities}/{entityId}/messages/{messageId} */
  updateMessage: async (
    entityType: string,
    entityId: UUID,
    messageId: UUID,
    dto: UpdateMessageRequest,
  ): Promise<BffMessageDto> => {
    const prefix = routePrefix(entityType);
    const res = await apiClient.put<BffResponse<BffMessageDto>>(
      `/${prefix}/${entityId}/messages/${messageId}`,
      dto,
    );
    return unwrap(res);
  },

  /** DELETE /{entities}/{entityId}/messages/{messageId} */
  deleteMessage: async (
    entityType: string,
    entityId: UUID,
    messageId: UUID,
  ): Promise<void> => {
    const prefix = routePrefix(entityType);
    await apiClient.delete(`/${prefix}/${entityId}/messages/${messageId}`);
  },
};
