import { UUID } from './common';

/**
 * Period Type for Statistics
 */
export enum StatisticsPeriod {
  Today = 'today',
  Week = 'week',
  Month = 'month',
  Quarter = 'quarter',
  Year = 'year',
  Custom = 'custom',
}

/**
 * Performance Overview Statistics
 */
export interface PerformanceStats {
  totalTasks: number;
  completedTasks: number;
  completionRate: number;
  totalTime: number; // in hours
  averageTimePerTask: number; // in hours
  averageRating: number;
  slaViolations: number;
  slaViolationRate: number;
  rank: number;
  totalEmployees: number;
  trend: {
    tasksChange: number; // percentage
    ratingChange: number; // absolute value
  };
}

/**
 * Performance Score Breakdown
 */
export interface PerformanceScore {
  overall: number;
  rating: string; // "Xuất sắc", "Tốt", "Trung bình"
  percentile: number;
  breakdown: {
    quality: number;
    speed: number;
    slaCompliance: number;
  };
}

/**
 * Trend Data Point
 */
export interface TrendDataPoint {
  label: string;
  completed: number;
  slaViolations: number;
}

/**
 * Priority Distribution
 */
export interface PriorityDistribution {
  urgent: number;
  high: number;
  medium: number;
  low: number;
}

/**
 * Category Distribution Item
 */
export interface CategoryDistributionItem {
  name: string;
  count: number;
  percentage: number;
  color: string;
}

/**
 * Monthly Comparison Data Point
 */
export interface MonthlyDataPoint {
  month: string;
  completed: number;
  slaViolations: number;
}

/**
 * Activity Heatmap Data
 */
export interface ActivityHeatmapData {
  hour: number;
  day: number; // 0 = Sunday, 6 = Saturday
  value: number; // number of tasks
}

/**
 * Personal Goal
 */
export interface PersonalGoal {
  id: UUID;
  title: string;
  description: string;
  target: number;
  current: number;
  unit: string;
  progress: number; // percentage
  deadline: string; // ISO date
  status: 'on-track' | 'at-risk' | 'completed' | 'overdue';
  category: 'productivity' | 'quality' | 'sla' | 'learning';
}

/**
 * Achievement Badge
 */
export interface AchievementBadge {
  id: UUID;
  name: string;
  description: string;
  icon: string; // Font Awesome icon class
  unlockedAt: string; // ISO date
  rarity: 'common' | 'rare' | 'epic' | 'legendary';
  category: 'milestone' | 'streak' | 'quality' | 'speed';
}

/**
 * AI Insight
 */
export interface AIInsight {
  id: UUID;
  type: 'recommendation' | 'warning' | 'achievement' | 'tip';
  title: string;
  message: string;
  icon: string;
  color: 'primary' | 'success' | 'warning' | 'danger' | 'info';
  actionable: boolean;
  action?: {
    label: string;
    url?: string;
  };
}

/**
 * Team Comparison Data
 */
export interface TeamComparison {
  myAverage: number;
  teamAverage: number;
  metric: string;
  difference: number; // percentage
  betterThanTeam: boolean;
}

/**
 * Complete Statistics Data
 */
export interface StatisticsData {
  period: StatisticsPeriod;
  startDate: string; // ISO date
  endDate: string; // ISO date
  performance: PerformanceStats;
  score: PerformanceScore;
  trends: TrendDataPoint[];
  priorityDistribution: PriorityDistribution;
  categoryDistribution: CategoryDistributionItem[];
  monthlyComparison: MonthlyDataPoint[];
  activityHeatmap: ActivityHeatmapData[];
  insights: AIInsight[];
  teamComparison: {
    completionRate: TeamComparison;
    averageTime: TeamComparison;
    qualityScore: TeamComparison;
  };
}

/**
 * Goals Response
 */
export interface GoalsData {
  goals: PersonalGoal[];
  achievementRate: number; // percentage of goals completed
}

/**
 * Achievements Response
 */
export interface AchievementsData {
  badges: AchievementBadge[];
  totalUnlocked: number;
  totalAvailable: number;
  recentUnlocks: AchievementBadge[];
}
