import React, { useState, useEffect } from 'react';
import { useAppDispatch } from '../../../../store/hooks';
import { createTicket } from '../../../../store/slices/ticketsSlice';
import {
  resetCreateTicketForm,
  addToast,
} from '../../../../store/slices/uiSlice';
import { TicketPriority, TicketCategory } from '../../../../models/Ticket';
import { Input } from '../../../../components/common/Input';
import { TextArea } from '../../../../components/common/TextArea';
import { Select } from '../../../../components/common/Select';
import { Button } from '../../../../components/common/Button';
import { FormActions } from '../../../../components/common/FormActions';
import { FileUploadArea } from '../../../../components/common/FileUploadArea';
import { useFormOptions } from '../../../../hooks/useFormOptions';
import styles from './CreateTicketForm.module.css';

export interface CreateTicketFormProps {
  onSuccess: () => void;
  onCancel: () => void;
}

export const CreateTicketForm: React.FC<CreateTicketFormProps> = ({
  onSuccess,
  onCancel,
}) => {
  const dispatch = useAppDispatch();
  const {
    loading: optLoading,
    defaultDepartmentId,
    departmentOptions,
    ticketPriorityOptions,
    ticketCategoryOptions,
  } = useFormOptions('create-ticket');

  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [priority, setPriority] = useState<string>('');
  const [category, setCategory] = useState<string>('');
  const [departmentId, setDepartmentId] = useState<string>('');
  const [loading, setLoading] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});

  // Pre-select the user's own department once options are loaded.
  useEffect(() => {
    if (!optLoading && defaultDepartmentId && !departmentId) {
      setDepartmentId(defaultDepartmentId);
    }
  }, [optLoading, defaultDepartmentId, departmentId]);

  const validate = (): boolean => {
    const newErrors: Record<string, string> = {};

    if (!title.trim()) {
      newErrors.title = 'Vui lòng nhập tiêu đề';
    }

    if (!description.trim()) {
      newErrors.description = 'Vui lòng nhập mô tả';
    }

    if (!priority) {
      newErrors.priority = 'Vui lòng chọn độ ưu tiên';
    }

    if (!category) {
      newErrors.category = 'Vui lòng chọn loại phiếu';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!validate()) {
      return;
    }

    setLoading(true);

    try {
      const selectedDept = departmentOptions.find(d => d.value === departmentId);
      const ticketData = {
        title:          title.trim(),
        description:    description.trim(),
        priority:       priority as TicketPriority,
        category:       category as TicketCategory,
        departmentName: selectedDept?.label,
      };

      await dispatch(createTicket(ticketData)).unwrap();

      dispatch(
        addToast({
          message: 'Tạo phiếu yêu cầu thành công',
          type: 'success',
        })
      );

      dispatch(resetCreateTicketForm());
      onSuccess();
    } catch (error: any) {
      dispatch(
        addToast({
          message: error.message || 'Có lỗi xảy ra khi tạo phiếu',
          type: 'error',
        })
      );
    } finally {
      setLoading(false);
    }
  };

  const handleReset = () => {
    setTitle('');
    setDescription('');
    setPriority('');
    setCategory('');
    setDepartmentId('');
    setErrors({});
    dispatch(resetCreateTicketForm());
    onCancel();
  };

  return (
    <form onSubmit={handleSubmit} className={styles.form}>
      <div className={styles.formContent}>
        <Input
          label="Tiêu đề"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          placeholder="Nhập tiêu đề phiếu yêu cầu"
          required
          fullWidth
          error={errors.title}
        />

        <TextArea
          label="Mô tả"
          value={description}
          onChange={(e) => setDescription(e.target.value)}
          placeholder="Mô tả chi tiết vấn đề hoặc yêu cầu"
          required
          fullWidth
          rows={6}
          error={errors.description}
        />

        <div className={styles.row}>
          <Select
            label="Độ ưu tiên"
            value={priority}
            onChange={(e) => setPriority(e.target.value)}
            options={ticketPriorityOptions}
            placeholder={optLoading ? 'Đang tải...' : 'Chọn độ ưu tiên'}
            disabled={optLoading}
            required
            fullWidth
            error={errors.priority}
          />

          <Select
            label="Loại phiếu"
            value={category}
            onChange={(e) => setCategory(e.target.value)}
            options={ticketCategoryOptions}
            placeholder={optLoading ? 'Đang tải...' : 'Chọn loại phiếu'}
            disabled={optLoading}
            required
            fullWidth
            error={errors.category}
          />
        </div>

        <div className={styles.row}>
          <Select
            label="Phòng ban"
            value={departmentId}
            onChange={(e) => setDepartmentId(e.target.value)}
            options={departmentOptions}
            placeholder={optLoading ? 'Đang tải danh sách...' : 'Chọn phòng ban (không bắt buộc)'}
            disabled={optLoading}
            fullWidth
          />
        </div>

        <div className={styles.uploadSection}>
          <label className={styles.sectionLabel}>Đính kèm file</label>
          <FileUploadArea
            value={[]}
            onChange={() => {}}
            maxSize={10}
            maxFiles={5}
            accept="*/*"
          />
        </div>
      </div>

      <FormActions align="end">
        <Button type="button" variant="secondary" onClick={handleReset}>
          <i className="fas fa-times"></i>
          Hủy
        </Button>
        <Button type="submit" variant="primary" loading={loading}>
          <i className="fas fa-paper-plane"></i>
          Tạo phiếu
        </Button>
      </FormActions>
    </form>
  );
};
