import React from 'react';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend,
} from 'chart.js';
import { Bar } from 'react-chartjs-2';
import { MonthlyDataPoint } from '../../../models/Statistics';
import { Card } from '../../common/Card';
import styles from './MonthlyComparison.module.css';

// Register ChartJS components
ChartJS.register(CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend);

interface MonthlyComparisonProps {
  data: MonthlyDataPoint[];
}

export const MonthlyComparison: React.FC<MonthlyComparisonProps> = ({ data }) => {
  const chartData = {
    labels: data.map((point) => point.month),
    datasets: [
      {
        label: 'Hoàn thành',
        data: data.map((point) => point.completed),
        backgroundColor: 'rgb(34, 197, 94)',
      },
      {
        label: 'Vi phạm SLA',
        data: data.map((point) => point.slaViolations),
        backgroundColor: 'rgb(239, 68, 68)',
      },
    ],
  };

  const options = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        position: 'bottom' as const,
      },
      tooltip: {
        backgroundColor: 'rgba(0, 0, 0, 0.8)',
        padding: 12,
      },
    },
    scales: {
      y: {
        beginAtZero: true,
        ticks: {
          precision: 0,
        },
      },
    },
  };

  return (
    <Card className={styles.chartCard}>
      <h3 className={styles.title}>
        <i className="fas fa-chart-bar" style={{ color: 'var(--primary-color)' }}></i>
        So sánh theo tháng
      </h3>
      <div className={styles.chartContainer}>
        <Bar data={chartData} options={options} />
      </div>
    </Card>
  );
};
